def split_blocks(txt):
    # returns list of ('text'|'table'|'figure', num, content)
    out=[]; pat=re.compile(r'^(\*\*(Table|Figure) (S\d+)\.\*\*.*)$',re.M)
    pos=0; ms_=list(pat.finditer(txt))
    for j,m in enumerate(ms_):
        if m.start()>pos: out.append(('text',None,txt[pos:m.start()]))
        end=ms_[j+1].start() if j+1<len(ms_) else len(txt)
        blk=txt[m.start():end]
        # table body ends at first blank line after a closing table rule; keep trailing prose separate
        out.append((m.group(2),m.group(3),blk)); pos=end
    if pos<len(txt): out.append(('text',None,txt[pos:]))
    return out
