def user_texts(fid):
    res=[]; off=0
    while True:
        r=host.frames(frame_id=fid, include_tool_results=False, max_results=500, offset=off)
        for m in r['messages']:
            if m.get('role')!='user': continue
            c=m.get('content')
            blocks=c if isinstance(c,list) else [{'type':'text','text':c}]
            for b in blocks:
                if isinstance(b,dict) and b.get('type')=='text':
                    t=b['text']
                    # strip system preambles
                    parts=[p for p in t.split('\n\n') if not p.startswith('[System]') and not p.startswith('Reference material') and not p.startswith('Keyword pre-scan') and not p.startswith('- ') and not p.startswith('Previously loaded')]
                    tt='\n'.join(parts).strip()
                    if tt and not tt.startswith('{') and not tt.startswith('<'): res.append(tt[:1500])
        if not r.get('truncated'): break
        off+=len(r['messages'])
    return res
